/**
 * Canonical Agent model — single source of truth for every antman
 * endpoint that returns an agent or a piece of one. Two endpoints
 * populate this type today:
 *
 *   - `Aspect.agentsV2` (catalog view from `GET /v1/apps/definition`)
 *     populates identity-only fields: `id`, `name`, `description`,
 *     `type`.
 *   - `GET /v1/agents/{agentId}` (full view) populates everything else
 *     based on the agent's variant (`type`).
 *
 * Different endpoints populate different fields on the same type;
 * every field that isn't required on both views is optional. Each
 * variant-specific field documents which `type` populates it.
 *
 * Variants come from antman's GraphQL union: `AgentElementum`,
 * `AgentExternal`, `AgentSystem`, `AgentComputerUse`, `AgentBrowserUse`,
 * `AgentSnowflake`, `AgentBedrock` — see `antman/.../AgentClient.java`'s
 * `getAgent` query for the source-of-truth fragment. Antman aliases
 * hydra's GraphQL `__typename` to `type` so the GraphQL-y field name
 * doesn't leak into antman's REST surface.
 *
 * `type` (the variant discriminator) and `systemType` (the
 * system-agent subtype, populated only on `AgentSystem`) are typed
 * as closed string-literal unions so the EDK can narrow on them at
 * compile time. They match hydra's `AgentType` and `AgentSystemType`
 * enums verbatim — keep in sync if either side changes
 * (`hydra/.../AgentType.java`, `hydra/.../AgentSystemType.java`).
 */
import type { Connection } from "../../../models/connection.js";
import type { AiProviderConnector } from "../../ai-provider-connectors/models/ai-provider-connector.js";
import type { Skill } from "../../skills/models/skill.js";
import type { AgentTool } from "./agent-tool.js";
/**
 * Closed set of agent variants antman emits. Six map 1:1 to hydra's
 * `AgentType` enum (`hydra/.../AgentType.java` — `ELEMENTUM`,
 * `EXTERNAL`, `SYSTEM`, `BROWSER_USE`, `SNOWFLAKE`, `BEDROCK`); the
 * seventh — `AgentComputerUse` — is a legacy variant antman still
 * surfaces but hydra has no V2 input for, so the EDK can read it
 * but cannot create/update it.
 */
export type AgentType = "AgentElementum" | "AgentExternal" | "AgentSystem" | "AgentComputerUse" | "AgentBrowserUse" | "AgentSnowflake" | "AgentBedrock";
/**
 * Closed set of system-agent subtypes — populated only when
 * `type === "AgentSystem"`. Mirrors hydra's `AgentSystemType`
 * enum (`hydra/.../AgentSystemType.java`). Distinct from `AgentType`:
 * one is the variant family, the other is the role within the
 * `AgentSystem` family.
 */
export type AgentSystemType = "GLOBAL" | "ASPECT_ADMIN" | "AUTOMATION_ADMIN" | "SKILL_BUILDER" | "DOCS_ASSISTANT";
/**
 * Closed set of `runAs` variants — mirrors hydra's
 * `AgentConversationRunAsType` enum
 * (`hydra/.../AgentConversationRunAsType.java`). Three values:
 *
 *   - `"AgentConversationRunAsUser"` — runs as a specific user
 *   - `"AgentConversationRunAsServiceAccount"` — runs as a service account
 *   - `"AgentConversationRunAsCurrentUser"` — runs as the invoking user
 *     at runtime (no fixed principal stored on the agent)
 */
export type AgentConversationRunAsType = "AgentConversationRunAsUser" | "AgentConversationRunAsServiceAccount" | "AgentConversationRunAsCurrentUser";
/**
 * `runAs` carries one of three shapes via inline-fragment narrowing
 * on antman's `AgentConversationRunAs` union. The query asks for
 * `id` on the embedded user/serviceAccount where applicable so the
 * EDK can resolve the principal without a follow-up call.
 *
 * Note: antman's GraphQL serializer emits unmatched union fields as
 * `null` rather than omitting them — so at runtime `user` and
 * `serviceAccount` will be `null` when the variant doesn't carry
 * that field. Code reading these should use optional chaining
 * (`runAs?.user?.id`) which treats null and undefined identically;
 * matches the convention across the rest of the entity-client.
 */
export interface AgentConversationRunAs {
    readonly type?: AgentConversationRunAsType;
    readonly id?: string;
    readonly user?: {
        readonly id: string;
    };
    readonly serviceAccount?: {
        readonly id: string;
    };
}
/**
 * Skill-access policy on the agent. Mirrors
 * `antman/.../SkillAccessConfig.java` — the `mode` value comes from
 * hydra's `SkillAccessMode` enum (`NONE` / `ALL` / `ALL_APP` /
 * `CUSTOM`). The `skills` and `preloadedSkills` lists are populated
 * only when `mode === "CUSTOM"`.
 */
export interface SkillAccessConfig {
    readonly mode: "NONE" | "ALL" | "ALL_APP" | "CUSTOM";
    readonly skills?: readonly {
        readonly id: string;
    }[];
    readonly preloadedSkills?: readonly {
        readonly id: string;
    }[];
}
export interface StartingActionVariableValidation {
    readonly pattern?: string;
    readonly minLength?: number;
    readonly maxLength?: number;
    readonly errorMessage?: string;
}
export interface StartingActionSelectOption {
    readonly value: string;
    readonly label: string;
}
export interface StartingActionVariable {
    readonly key: string;
    readonly label: string;
    readonly placeholder?: string;
    readonly type: string;
    readonly required: boolean;
    readonly options?: readonly StartingActionSelectOption[];
    readonly validation?: StartingActionVariableValidation;
}
export interface StartingAction {
    readonly id: string;
    readonly name: string;
    readonly prompt: string;
    readonly icon?: string;
    readonly order: number;
    readonly enabled: boolean;
    readonly variables: readonly StartingActionVariable[];
}
/**
 * Snowflake-variant configuration. Populated only when
 * `type === "AgentSnowflake"`. The `aiProvider` reference
 * carries identity only; the rest are per-warehouse routing fields.
 */
export interface AgentSnowflakeConfig {
    readonly aiProvider?: {
        readonly id: string;
    };
    readonly database?: string;
    readonly schema?: string;
    readonly name?: string;
}
/**
 * Bedrock-variant configuration. Populated only when
 * `type === "AgentBedrock"`.
 */
export interface AgentBedrockConfig {
    readonly aiProvider?: {
        readonly id: string;
    };
    readonly agentArn?: string;
}
/**
 * JWT key source — the flat read shape. `type` is the variant
 * discriminator, aliased from hydra's `__typename`. Exactly one
 * variant field is populated per the discriminator.
 */
export interface AgentAuthenticationJwtKeySourceWire {
    readonly type?: "AgentAuthenticationJwtPlainTextSource" | "AgentAuthenticationJwtJwksSource";
    readonly plainTextKeyValuePem?: string;
    readonly jwksUrl?: string;
}
export interface AgentAuthenticationJwtClaimRequirement {
    readonly claimName: string;
    readonly acceptableValues: readonly string[];
}
export interface AgentAuthenticationJwt {
    readonly enabled: boolean;
    readonly headerName: string;
    readonly emailAddressClaimName: string;
    readonly keySource: AgentAuthenticationJwtKeySourceWire;
    readonly requiredClaims?: readonly AgentAuthenticationJwtClaimRequirement[];
}
/** Agent authentication config (JWT only today). */
export interface AgentAuthentication {
    readonly jwt?: AgentAuthenticationJwt;
}
/**
 * An A2A skill advertised on an agent's card (for agent-to-agent
 * discovery).
 */
export interface AgentA2ASkill {
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly tags?: readonly string[];
    readonly examples?: readonly string[];
    readonly inputModes?: readonly string[];
    readonly outputModes?: readonly string[];
}
/** An agent's A2A card. */
export interface AgentCard {
    readonly skills?: Connection<AgentA2ASkill>;
}
/**
 * An agent as it appears in either the catalog view (identity only)
 * or the full GET-by-id view (everything its variant carries).
 *
 * `type` is the variant discriminator — narrow on it before reading
 * variant-specific fields. Shared fields (id, name, description,
 * runAs, startingActions, skillAccessConfig, skills) are populated
 * for every variant; variant-specific fields document which `type`
 * populates them inline.
 *
 * `app` is the owning aspect (catalog view's owner reference). Every
 * variant except `AgentSystem` carries it (system agents have no app
 * owner).
 */
export interface Agent {
    readonly type: AgentType;
    readonly id: string;
    readonly name: string;
    /** Server-assigned stable handle (e.g. `AGT_t2cq695s`); preferred over a name-derived handle. */
    readonly clientHandle?: string;
    /**
     * Immutable creation timestamp (ISO-8601). Primary ordering key for
     * deterministic handle minting (`src/handles`); optional, falls back to
     * `id` ordering when absent.
     */
    readonly createdAt?: string;
    readonly description: string;
    readonly temperature: number;
    readonly maxLength: number;
    readonly reasoningEffort?: string;
    readonly runAs?: AgentConversationRunAs;
    readonly agentAuthentication?: AgentAuthentication;
    readonly startingActions?: readonly StartingAction[];
    readonly skillAccessConfig?: SkillAccessConfig;
    readonly skills?: Connection<Skill>;
    readonly tools?: Connection<AgentTool>;
    readonly card?: AgentCard;
    readonly app?: {
        readonly id: string;
    };
    readonly firstMessage?: string;
    readonly instructions: string;
    readonly aiProviderConnector: AiProviderConnector;
    readonly systemType?: AgentSystemType;
    readonly browserAgentInstructions?: string;
    readonly persistSession?: boolean;
    readonly flashMode?: boolean;
    readonly vision?: boolean;
    readonly sessionTimeoutMinutes?: number;
    readonly agentSnowflakeConfig?: AgentSnowflakeConfig;
    readonly agentBedrockConfig?: AgentBedrockConfig;
}
